-- 000093_runtime_identity_hardening
--
-- Trace policies gain match_comm_mode (exact | word | substring). Every
-- policy that exists today was written for case-insensitive substring
-- matching, so the column defaults to 'substring' and existing rows keep
-- that behaviour. The control plane writes the mode explicitly: new policies
-- get 'word' (a kill for "nc" no longer hits runc or rsync). The column
-- default stays 'substring' so a control plane older than the column, still
-- writing rows during a rolling upgrade, stores what its agents do.
--
-- Built-in detection rules no longer drop events on a process name the
-- process chose itself (prctl(PR_SET_NAME)).
--   * Suppress rules for systemd and dockerd additionally require
--     exe_verified: the kernel saw the process in the agent-verified
--     protected set when it produced the event.
--   * Name-only suppress rules become downgrades that keep the event and tag
--     it unverified-identity (renamed "Suppress ..." -> "Downgrade ...").
--   * The sshd host-key and account-database downgrades require exe_verified,
--     so a process and parent renamed to sshd reading /etc/shadow stay HIGH.
-- Only name, description, action, conditions, severity_override and tags of
-- built-in rows change; enabled (the one field a user can edit on a built-in)
-- and the row IDs are never touched. Custom rules are not touched.

ALTER TABLE ebpf_trace_policies
    ADD COLUMN IF NOT EXISTS match_comm_mode VARCHAR(16) NOT NULL DEFAULT 'substring';
ALTER TABLE ebpf_trace_policies
    ADD CONSTRAINT ebpf_trace_policies_match_comm_mode_check
    CHECK (match_comm_mode IN ('exact', 'word', 'substring'));

UPDATE trace_detection_rules SET name = 'Downgrade runc process clone', description = 'runc clones namespaces during container startup. This is expected. The process name is not verified, so the event is kept and tagged. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'downgrade', conditions = '[{"field":"comm","op":"starts_with","value":"runc"},{"field":"event_name","op":"eq","value":"clone"},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["container","false-positive","unverified-identity"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress runc process clone';
UPDATE trace_detection_rules SET name = 'Downgrade WAFio agent AF_NETLINK socket', description = 'WAFio agents create AF_NETLINK (family 16) sockets for network monitoring. This is expected. The process name is not verified, so the event is kept and tagged. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'downgrade', conditions = '[{"field":"comm","op":"contains","value":"wafio"},{"field":"event_name","op":"eq","value":"socket"},{"field":"addr_family","op":"eq","value":16},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["wafio","false-positive","unverified-identity"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress WAFio agent AF_NETLINK socket';
UPDATE trace_detection_rules SET name = 'Suppress systemd service start execve', description = 'systemd calls execve to start services. These are not process injection. Only for a process the agent verified as the systemd host binary (or its child before exec); the name alone is not enough. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'suppress', conditions = '[{"field":"comm","op":"eq","value":"systemd"},{"field":"event_name","op":"eq","value":"execve"},{"field":"exe_verified","op":"eq","value":true},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["systemd","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress systemd service start execve';
UPDATE trace_detection_rules SET name = 'Downgrade cron job execution', description = 'cron executing scheduled jobs via execve is normal operation. The process name is not verified, so the event is kept and tagged. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'downgrade', conditions = '[{"field":"comm","op":"in","value":["cron","crond"]},{"field":"event_name","op":"eq","value":"execve"},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["cron","false-positive","unverified-identity"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress cron job execution';
UPDATE trace_detection_rules SET name = 'Downgrade logrotate log access', description = 'logrotate accessing /var/log is its intended purpose. The process name is not verified, so the event is kept and tagged. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'downgrade', conditions = '[{"field":"comm","op":"eq","value":"logrotate"},{"field":"filename","op":"starts_with","value":"/var/log/"},{"field":"severity","op":"lte","value":2},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["logrotate","false-positive","unverified-identity"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress logrotate log access';
UPDATE trace_detection_rules SET name = 'Downgrade apt/dpkg package management', description = 'apt and dpkg running execve during package operations is expected. The process name is not verified, so the event is kept and tagged. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'downgrade', conditions = '[{"field":"comm","op":"in","value":["apt","apt-get","dpkg","dpkg-deb","apt-cache"]},{"field":"event_name","op":"eq","value":"execve"},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["package-manager","false-positive","unverified-identity"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress apt/dpkg package management';
UPDATE trace_detection_rules SET name = 'Downgrade local health-check curl', description = 'curl connecting to 127.0.0.1 or localhost is typically a health check probe. The process name is not verified, so the event is kept and tagged. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'downgrade', conditions = '[{"field":"comm","op":"eq","value":"curl"},{"field":"addr","op":"eq","value":"127.0.0.1"},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["health-check","false-positive","unverified-identity"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress local health-check curl';
UPDATE trace_detection_rules SET name = 'Suppress dockerd network management', description = 'dockerd creating/managing network sockets is normal container networking. Only for a process the agent verified as the dockerd host binary; a process renamed to dockerd is kept. Applies only below HIGH severity; process names alone do not justify hiding sensitive observations.', action = 'suppress', conditions = '[{"field":"comm","op":"eq","value":"dockerd"},{"field":"category","op":"eq","value":"network"},{"field":"exe_verified","op":"eq","value":true},{"field":"severity","op":"lte","value":2}]'::jsonb, severity_override = NULL, tags = ARRAY(SELECT jsonb_array_elements_text('["docker","false-positive"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Suppress dockerd network management';
UPDATE trace_detection_rules SET name = 'Downgrade sshd host key reads', description = 'sshd loads its own host keys on every connection. Reading /etc/ssh/* is the daemon doing its job. Only for a process the agent verified as the sshd host binary.', action = 'downgrade', conditions = '[{"field":"comm","op":"eq","value":"sshd"},{"field":"parent_comm","op":"eq","value":"sshd"},{"field":"event_name","op":"eq","value":"openat"},{"field":"filename","op":"starts_with","value":"/etc/ssh/"},{"field":"exe_verified","op":"eq","value":true},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["ssh","expected"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade sshd host key reads';
UPDATE trace_detection_rules SET name = 'Downgrade sshd account database reads', description = 'sshd reads the account database during authentication and session setup. Only for a process the agent verified as the sshd host binary: a process and parent renamed to sshd reading /etc/shadow stay HIGH.', action = 'downgrade', conditions = '[{"field":"comm","op":"eq","value":"sshd"},{"field":"parent_comm","op":"eq","value":"sshd"},{"field":"event_name","op":"eq","value":"openat"},{"field":"filename","op":"in","value":["/etc/passwd","/etc/shadow","/etc/group","/etc/gshadow","/etc/nsswitch.conf"]},{"field":"exe_verified","op":"eq","value":true},{"field":"event_name","op":"eq","value":"openat"},{"field":"flags","op":"bit_none","value":579}]'::jsonb, severity_override = 1, tags = ARRAY(SELECT jsonb_array_elements_text('["ssh","auth","expected"]'::jsonb)), updated_at = NOW() WHERE built_in = true AND name = 'Downgrade sshd account database reads';
